// Generated by Claude Code — CS 3660 Sprint 2
// time-travel-slider: Lit Element component. A range slider that lets the
// operator drag to any past timestamp. When moved it fires a 'time-travel'
// custom event with the chosen ISO timestamp so the parent page can fetch
// the reconstructed fleet state for that point in time. When dragged all the
// way to the right (latest), it emits { live: true } to resume the live view.

import { LitElement, html, css } from 'lit';

export class TimeTravelSlider extends LitElement {
  static properties = {
    earliest: { type: String }, // ISO string — first event in the store
    latest:   { type: String }, // ISO string — most recent event
    _value:   { type: Number, state: true }, // 0..1000 slider ticks
    _isLive:  { type: Boolean, state: true },
  };

  static styles = css`
    :host { display: block; font-family: system-ui, sans-serif; }

    .wrapper {
      display: flex;
      align-items: center;
      gap: .75rem;
      padding: .5rem 0;
    }

    label { color: #9ca3af; font-size: .8rem; white-space: nowrap; }

    input[type=range] {
      flex: 1;
      accent-color: #6366f1;
      height: 4px;
      cursor: pointer;
    }

    .timestamp {
      font-size: .8rem;
      color: #f9fafb;
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
      min-width: 11rem;
      text-align: right;
    }

    .live-badge {
      background: #22c55e;
      color: #fff;
      font-size: .7rem;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 9999px;
    }
  `;

  static TICKS = 1000;

  constructor() {
    super();
    this.earliest = null;
    this.latest   = null;
    this._value   = TimeTravelSlider.TICKS; // start at live (rightmost)
    this._isLive  = true;
  }

  // Convert slider tick (0..TICKS) to an ISO timestamp within [earliest, latest]
  _tickToIso(tick) {
    if (!this.earliest || !this.latest) return null;
    const start = new Date(this.earliest).getTime();
    const end   = new Date(this.latest).getTime();
    if (start >= end) return null;
    const ms = start + (tick / TimeTravelSlider.TICKS) * (end - start);
    return new Date(ms).toISOString();
  }

  _formatIso(iso) {
    if (!iso) return '--';
    return new Date(iso).toLocaleString(undefined, {
      month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
  }

  _onInput(e) {
    const tick = parseInt(e.target.value, 10);
    this._value  = tick;
    this._isLive = tick >= TimeTravelSlider.TICKS;

    if (this._isLive) {
      this.dispatchEvent(new CustomEvent('time-travel', {
        bubbles: true, composed: true,
        detail: { live: true },
      }));
    } else {
      const iso = this._tickToIso(tick);
      if (iso) {
        this.dispatchEvent(new CustomEvent('time-travel', {
          bubbles: true, composed: true,
          detail: { live: false, upToTime: iso },
        }));
      }
    }
  }

  render() {
    const hasRange = this.earliest && this.latest;
    const iso      = this._isLive ? null : this._tickToIso(this._value);

    return html`
      <div class="wrapper">
        <label>Time travel</label>
        <input
          type="range"
          min="0"
          max="${TimeTravelSlider.TICKS}"
          .value="${this._value}"
          ?disabled="${!hasRange}"
          @input="${this._onInput}"
        />
        <span class="timestamp">
          ${this._isLive
            ? html`<span class="live-badge">LIVE</span>`
            : this._formatIso(iso)
          }
        </span>
      </div>
    `;
  }
}

customElements.define('time-travel-slider', TimeTravelSlider);
